using ASMILE.BO.Core.FrontOffice.Foundation.Identifiers;

namespace ASMILE.BO.Core.FrontOffice.HotelMasterData;

public enum HotelWakeupRuleKind { Manual = 1, Scheduled = 2, Confirmation = 3, Escalation = 4 }

public sealed class HotelWakeupRuleProfile
{
    private HotelWakeupRuleProfile() { }
    public Guid HotelWakeupRuleProfileId { get; private set; } public Guid PropertyId { get; private set; } public string Code { get; private set; } = string.Empty; public string Name { get; private set; } = string.Empty; public HotelWakeupRuleKind Kind { get; private set; } public int DefaultLeadMinutes { get; private set; } public int EscalationMinutes { get; private set; } public bool ConfirmationRequired { get; private set; } public string NotificationChannel { get; private set; } = string.Empty; public DateTime EffectiveFrom { get; private set; } public DateTime EffectiveTo { get; private set; } public string? Description { get; private set; } public bool IsActive { get; private set; } public DateTime CreatedAtUtc { get; private set; } public Guid? CreatedBy { get; private set; } public DateTime UpdatedAtUtc { get; private set; } public Guid? UpdatedBy { get; private set; } public byte[]? RowVersion { get; private set; }
    public static HotelWakeupRuleProfile Create(PropertyId propertyId, string code, string name, HotelWakeupRuleKind kind, int defaultLeadMinutes, int escalationMinutes, bool confirmationRequired, string notificationChannel, DateTime from, DateTime to, string? description, DateTime nowUtc, ActorId? actorId) { Validate(code, name, kind, defaultLeadMinutes, escalationMinutes, notificationChannel, from, to); return new() { HotelWakeupRuleProfileId = Uuid7.NewGuid(), PropertyId = propertyId.Value, Code = CodeValue(code), Name = name.Trim(), Kind = kind, DefaultLeadMinutes = defaultLeadMinutes, EscalationMinutes = escalationMinutes, ConfirmationRequired = confirmationRequired, NotificationChannel = notificationChannel.Trim(), EffectiveFrom = from.Date, EffectiveTo = to.Date, Description = Normalize(description), IsActive = true, CreatedAtUtc = nowUtc, CreatedBy = actorId?.Value, UpdatedAtUtc = nowUtc, UpdatedBy = actorId?.Value }; }
    public void Update(string code, string name, HotelWakeupRuleKind kind, int defaultLeadMinutes, int escalationMinutes, bool confirmationRequired, string notificationChannel, DateTime from, DateTime to, string? description, DateTime nowUtc, ActorId? actorId) { Validate(code, name, kind, defaultLeadMinutes, escalationMinutes, notificationChannel, from, to); Code = CodeValue(code); Name = name.Trim(); Kind = kind; DefaultLeadMinutes = defaultLeadMinutes; EscalationMinutes = escalationMinutes; ConfirmationRequired = confirmationRequired; NotificationChannel = notificationChannel.Trim(); EffectiveFrom = from.Date; EffectiveTo = to.Date; Description = Normalize(description); Touch(nowUtc, actorId); }
    public void Activate(DateTime nowUtc, ActorId? actorId) { IsActive = true; Touch(nowUtc, actorId); } public void Deactivate(DateTime nowUtc, ActorId? actorId) { IsActive = false; Touch(nowUtc, actorId); }
    private static void Validate(string code, string name, HotelWakeupRuleKind kind, int lead, int escalation, string channel, DateTime from, DateTime to) { if (string.IsNullOrWhiteSpace(code)) throw new ArgumentException("HOTEL_WAKEUP_RULE_CODE_REQUIRED"); if (string.IsNullOrWhiteSpace(name)) throw new ArgumentException("HOTEL_WAKEUP_RULE_NAME_REQUIRED"); if (!Enum.IsDefined(kind)) throw new ArgumentException("HOTEL_WAKEUP_RULE_KIND_INVALID"); if (lead < 0 || escalation < 0) throw new ArgumentException("HOTEL_WAKEUP_RULE_MINUTES_INVALID"); if (string.IsNullOrWhiteSpace(channel)) throw new ArgumentException("HOTEL_WAKEUP_RULE_CHANNEL_REQUIRED"); if (to.Date < from.Date) throw new ArgumentException("HOTEL_WAKEUP_RULE_EFFECTIVE_RANGE_INVALID"); }
    private static string CodeValue(string value) => value.Trim().ToUpperInvariant(); private static string? Normalize(string? value) => string.IsNullOrWhiteSpace(value) ? null : value.Trim(); private void Touch(DateTime nowUtc, ActorId? actorId) { UpdatedAtUtc = nowUtc; UpdatedBy = actorId?.Value; }
}
